use vstd::prelude::*;

verus! {

fn reverse_string(s: &Vec<char>) -> (result: Vec<char>)
    ensures
        // The result has the same length as the input
        result.len() == s.len(),
        // And for every valid index i, result[i] = s[s.len() - 1 - i]
        forall |i: usize| i < s.len() ==> result[i] == s[s.len() - 1 - i],
{
    let mut res: Vec<char> = Vec::new();
    let n = s.len();
    let mut i: usize = 0;
    // Build the reversed vector one element at a time
    while i < n
        invariant
            // We have processed i elements so far
            i <= n,
            // The accumulated result has length i
            res.len() == i,
            // And for every j < i, res[j] equals the corresponding reversed element of s
            forall |j: usize| j < i ==> res[j] == s[n - 1 - j],
        decreases n - i,
    {
        // Take the element from the "back" of s
        let ch: char = s[n - 1 - i];
        // Push it onto the result
        res.push(ch);
        i += 1;
    }
    res
}

} // verus!

